'use strict';
// A browser-local convenience lock, not account security. Change this value to set a new password.
const DEBUG_PASSWORD='voiddebug';
const VoidGuide=(()=>{
 const enemies={
  chaser:{name:'Chaser',behavior:'Follows you continuously and deals contact damage.',counter:'Keep moving. Sweep nearby groups with your dollar stack.'},
  charger:{name:'Charger',behavior:'Shows an arrow before rushing in a straight line.',counter:'Step sideways after the warning, or jump across its path.'},
  shooter:{name:'Shooter',behavior:'Approaches firing range, then sends aimed shots. Chapter 3 uses a drone variant.',counter:'Move across its line of fire and close in between shots.'},
  turret:{name:'Spread Turret',behavior:'Stays in place and fires a five-shot fan.',counter:'Move between volleys, then approach from the side.'},
  shield:{name:'Shield Guard',behavior:'Faces you quickly and blocks attacks from the front.',counter:'Jump close: landing stuns it and breaks its shield for 3 seconds.'},
  splitter:{name:'Splitter',behavior:'Chases you and splits into two fast, fragile offspring on death.',counter:'Leave room for the offspring. Landing and wide swings help clear them.'},
  mini:{name:'Split Offspring',behavior:'A fast one-HP enemy created by a defeated Splitter.',counter:'One melee hit clears it. Avoid letting several surround you.'}
 };
 const bosses=[
  {kind:'biden',attacks:'Five urine droplets in a fan, plus one slow homing poop projectile. Hits leave no slowing pool.',counter:'Keep circling to draw the homing shot away, then step in for a swing. The diaper is cosmetic.'},
  {kind:'pooh',attacks:'A rotating 12-shot ring followed by three fast aimed shots.',counter:'Let the aimed burst pass, move through a gap, and watch the conveyor direction.'},
  {kind:'mojtaba',attacks:'Rotating bullet rings and a warned explosion at your position. Additional bombardments escalate at health thresholds. His bombs hurt you and minions, but not him.',counter:'Leave red circles before they detonate. Save your jump for a blocked escape route.'}
 ];
 function bossStats(chapter){const g=new VoidArena.Arena(()=>.5);g.chapter=chapter;g.setupChapter();g.createBoss();const b=g.boss;g.fireOriginalBoss(b,0);const normal={shots:g.room.bullets.length,interval:b.cd};g.room.bullets=[];b.hp=b.maxhp*.49;g.fireOriginalBoss(b,0);return{hp:b.maxhp,speed:b.speed,normal,enraged:{shots:g.room.bullets.length,interval:b.cd}};}
 return{enemies,bosses,bossStats};
})();
function createDebugCodex({game,releaseInput,syncOverlay,hud,drawEnemy,drawPerson}){
 const {TYPES,THEMES,WAVES,ITEMS,synergy}=VoidArena;
 const dialog=document.getElementById('debug-window'),body=document.getElementById('debug-body');
 let unlocked=false,opened=false,returnMode='menu',tab='debug';
 const tabs=[['debug','Debug'],['enemies','Enemies · 7'],['items','Items · 6'],['bosses','Bosses · 3']];
 const escape=value=>String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const bind=(id,fn)=>document.getElementById(id).onclick=fn;
 const facts=(pairs)=>'<dl class="codex-facts">'+pairs.map(([key,value])=>'<div><dt>'+escape(key)+'</dt><dd>'+escape(value)+'</dd></div>').join('')+'</dl>';
 const image=(kind,key,name)=>'<canvas class="codex-art" width="140" height="120" data-guide-kind="'+kind+'" data-guide-key="'+key+'" role="img" aria-label="'+escape(name)+' illustration"></canvas>';
 function paintArt(){for(const el of body.querySelectorAll('canvas[data-guide-kind]')){const c=el.getContext('2d');c.clearRect(0,0,140,120);if(el.dataset.guideKind==='boss'){drawPerson(VoidGuide.bosses[Number(el.dataset.guideKey)].kind,c);}else{const type=el.dataset.guideKey,cfg=TYPES[type];drawEnemy({...cfg,type,x:70,y:66,maxhp:cfg.hp,age:0,flash:0,face:0,t:1,charge:0,broken:0,stun:0,tax:0},c);}}}
 function debugPage(){return '<p class="codex-intro">Test a wave or a Boss directly. Jumps restore hearts and cooldowns, clear temporary combat effects, and keep your items.</p><div class="debug-summary"><span><b>3</b> chapters</span><span><b>7</b> enemy types</span><span><b>6</b> build items</span></div><section class="debug-toggle"><div><h3>Infinite hearts</h3><p>Ignore damage. Turn it off to test survival again. Restart turns it off.</p></div><button type="button" id="debug-infinite" aria-pressed="'+game.debugInvincible+'" class="debug-switch">'+(game.debugInvincible?'ON · INVINCIBLE':'OFF')+'</button></section><div class="debug-chapters">'+THEMES.map((theme,i)=>'<article class="codex-card"><div class="codex-eyebrow">CHAPTER 0'+(i+1)+'</div><h3>'+theme.name+'</h3>'+facts([['Wave',WAVES[i].count+' enemies'],['Boss',theme.hp+' HP']])+'<p>'+(i===0?'Open arena. Urine fans and homing poop.':i===1?'Conveyors push grounded fighters.':'Missile warnings and escalating bombardments.')+'</p><div class="debug-actions"><button type="button" id="debug-wave-'+i+'">Start wave ↗</button><button type="button" id="debug-boss-'+i+'">Start Boss ↗</button></div></article>').join('')+'</div><p class="codex-note">Actions start the selected fight immediately. Invincibility stays on across debug jumps, and resets on Restart.</p>';}
 function enemiesPage(){return '<p class="codex-intro">Recognize the silhouette, understand the attack, choose your response. HP and movement speeds below come from the live enemy definitions.</p><div class="codex-grid">'+Object.entries(TYPES).map(([id,type])=>{const entry=VoidGuide.enemies[id];const chapters=WAVES.flatMap((wave,i)=>wave.roster.includes(id)?[i+1]:[]);return '<article class="codex-card"><div class="codex-cardhead">'+image('enemy',id,entry.name)+'<div><div class="codex-eyebrow">'+(id==='mini'?'SPAWNED BY SPLITTERS':'CHAPTERS '+chapters.join(' / '))+'</div><h3>'+entry.name+'</h3></div></div>'+facts([['HP',type.hp],['Move',type.speed+' px/s']])+'<p>'+entry.behavior+'</p><div class="codex-counter"><b>COUNTER</b> '+entry.counter+'</div></article>';}).join('')+'</div><p class="codex-note">Movement is baseline ground speed; charges, tariffs and conveyors can change it. All enemy contact and projectiles cost one heart per hit, subject to invulnerability.</p>';}
 function itemsPage(){return '<p class="codex-intro">After each of the first two Bosses, clear the minions and walk into the health kit to restore 2 hearts and open the item choices. Two picks per normal campaign. Choose one of three unowned items. Your second offer includes a supported synergy.</p><div class="codex-basics"><b>SPACE · JUMP</b><span>Avoid damage in the air. Landing stuns normal enemies, breaks shields, grants 0.3s protection and separates overlapping bodies.</span><b>Q · TARIFF</b><span>5-second stationary zone, 12-second cooldown. Slows normal movement by 40% and lengthens their attack intervals by 30%; slows Boss movement by 20%.</span></div><div class="codex-grid">'+ITEMS.map(item=>{const partners=ITEMS.filter(other=>synergy(item.id,other.id));return '<article class="codex-card"><div class="codex-cardhead"><span class="codex-itemart" aria-hidden="true">'+item.icon+'</span><div><div class="codex-eyebrow">'+(game.has(item.id)?'IN YOUR BUILD':'BUILD ITEM')+'</div><h3>'+item.name+'</h3></div></div><p>'+item.desc+'</p><div class="codex-counter"><b>SUPPORTED SYNERGIES</b><ul>'+partners.map(other=>'<li><strong>'+other.name+'</strong> — '+synergy(item.id,other.id)+'</li>').join('')+'</ul></div></article>';}).join('')+'</div>';}
 function bossesPage(){return '<p class="codex-intro">Bosses use the current original three-chapter patterns. All fire faster below half health. Defeating a Boss does not remove any surviving enemies.</p><div class="codex-grid">'+THEMES.map((theme,i)=>{const entry=VoidGuide.bosses[i],stats=VoidGuide.bossStats(i+1);return '<article class="codex-card"><div class="codex-cardhead">'+image('boss',i,theme.name)+'<div><div class="codex-eyebrow">CHAPTER 0'+(i+1)+'</div><h3>'+theme.name+'</h3></div></div>'+facts([['HP',stats.hp],['Move',stats.speed+' px/s'],['Volley',stats.normal.shots+' → '+stats.enraged.shots+' shots'],['Interval',stats.normal.interval+'s → '+stats.enraged.interval+'s']])+'<p>'+entry.attacks+'</p><div class="codex-counter"><b>COUNTER</b> '+entry.counter+'</div></article>';}).join('')+'</div><p class="codex-note">Arrow values show normal → below-half-health behavior. All Bosses briefly stagger when you land nearby, with resistance to repeated stuns.</p>';}
 function render(focusId){if(!unlocked){body.innerHTML='<div class="debug-lock"><div class="codex-eyebrow">LOCAL DEBUG ACCESS</div><h3>Unlock the test bench.</h3><p>Enter the debug password. The window pauses combat while you browse.</p><form id="debug-unlock-form"><label for="debug-password">Password</label><div class="debug-passwordrow"><input id="debug-password" type="password" autocomplete="off" maxlength="64" required><button type="submit">Unlock ↗</button></div><p id="debug-error" role="alert" aria-live="polite"></p></form><p class="codex-note">Browser-local convenience lock. Unlock lasts until this page reloads.</p></div>';document.getElementById('debug-unlock-form').onsubmit=e=>{e.preventDefault();const input=document.getElementById('debug-password');if(input.value===DEBUG_PASSWORD){input.value='';unlocked=true;render();}else{document.getElementById('debug-error').textContent='Incorrect password. Try again.';input.value='';input.focus();}};document.getElementById('debug-password').focus();return;}
 body.innerHTML='<nav class="codex-nav" aria-label="Debug and guide sections">'+tabs.map(([id,title])=>'<button type="button" id="debug-tab-'+id+'" aria-pressed="'+(tab===id)+'">'+title+'</button>').join('')+'</nav><div class="codex-content">'+({debug:debugPage,enemies:enemiesPage,items:itemsPage,bosses:bossesPage}[tab])()+'</div>';
 for(const [id]of tabs)bind('debug-tab-'+id,()=>{tab=id;render();});
 if(tab==='debug'){bind('debug-infinite',()=>{game.setDebugInvincible(!game.debugInvincible);hud();render('debug-infinite');});for(let i=0;i<THEMES.length;i++){bind('debug-wave-'+i,()=>jump(i+1,false));bind('debug-boss-'+i,()=>jump(i+1,true));}}
 paintArt();document.getElementById(focusId||'debug-tab-'+tab).focus();}
 function open(){if(opened)return;returnMode=game.mode;releaseInput();game.mode='debug';opened=true;syncOverlay();dialog.showModal();render();}
 function close(){if(!opened)return;opened=false;releaseInput();game.mode=returnMode;dialog.close();syncOverlay();hud();document.getElementById('debug-open').focus();}
 function jump(chapter,bossFight){if(!opened||!unlocked)return false;if(!game.debugJump(chapter,bossFight))return false;returnMode='play';close();return true;}
 bind('debug-open',open);bind('debug-close',close);
 dialog.addEventListener('cancel',e=>{e.preventDefault();close();});dialog.addEventListener('close',()=>{if(opened)close();});
 return{open,close,isOpen:()=>opened};
}
